if (N <= 0) return 0.0;
    if (N % 2 != 0) N++; // Ensure N is even as per Simpson's rule requirement

    double h = (b - a) / N;
    double integral = f(a) + f(b);

    for (int i = 1; i < N; ++i) {
        double x = a + i * h;
        if (i % 2 == 0) {
            integral += 2.0 * f(x);
        } else {
            integral += 4.0 * f(x);
        }
    }

    return (h / 3.0) * integral;

